<h2>Validate, format or minify JSON</h2><p class="lead">Process JSON locally in your browser and get an exact parse error when the input is invalid.</p><div class="form-grid"><div class="field full"><label for="input">JSON input</label><textarea id="input" style="min-height:230px">{"site":"ToolboxKart","categories":["SEO","Marketing","Finance"],"active":true}</textarea></div></div><div class="tool-actions"><button class="btn btn-primary" id="pretty">Format</button><button class="btn btn-secondary" id="minify">Minify</button><button class="btn btn-secondary" id="copy">Copy output</button></div><div id="status" class="notice"></div><div class="result-box"><pre class="code-output" id="out"></pre></div>
<script>(()=>{const $=i=>document.getElementById(i);function run(space){try{const x=JSON.parse($('input').value);$('out').textContent=JSON.stringify(x,null,space);$('status').innerHTML='<strong class="success">Valid JSON</strong> — parsed successfully.'}catch(e){$('out').textContent='';$('status').innerHTML='<strong class="danger">Invalid JSON</strong> — '+String(e.message).replace(/[&<>]/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[s]))}}$('pretty').onclick=()=>run(2);$('minify').onclick=()=>run(0);$('copy').onclick=()=>tkCopy($('out').textContent);run(2)})();</script>
